-- A `uuid` is 16 bytes aligned to 1 (`typalign` `c`), so it packs right after a 2-byte short
-- varlena: `(text 'a', uuid, text)` holds 2 672 characters.
-- @setup
CREATE TABLE t (a text, b uuid, c text);
CREATE INDEX t_i ON t (a, b, c);
INSERT INTO t VALUES ('a', '00000000-0000-0000-0000-000000000001', '');
-- @test
-- @profile-lock
SELECT count(*) FROM t;
